CREATE TABLE leads (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    applicant_name TEXT NOT NULL,
    phone TEXT NOT NULL,
    sector TEXT NOT NULL,
    salary TEXT,
    commitment TEXT,
    loan_purpose TEXT DEFAULT 'Penyatuan Hutang',
    credit_issues TEXT,
    assigned_agent_id INTEGER,
    status TEXT DEFAULT 'BARU', 
    notes TEXT,
    source TEXT DEFAULT 'Website Wizard',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, ic_number TEXT, location_state TEXT, employer_name TEXT, employment_status TEXT, professional_cert TEXT, social_channel TEXT,
    FOREIGN KEY(assigned_agent_id) REFERENCES agents(id)
);
CREATE TABLE testimonials (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    client_name TEXT NOT NULL,
    profession TEXT NOT NULL,
    original_issue TEXT NOT NULL,
    loan_approved TEXT NOT NULL,
    monthly_savings TEXT,
    story TEXT,
    is_featured INTEGER DEFAULT 1,
    display_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
